/**
 * HubSpot's crm_event delivery, VERIFIED before the app sees it: the raw body
 * exactly as received, the headers, and the request line, checked by the trigger's own
 * scheme (hmac). A delivery that does not verify answers 401 with the
 * reason and dispatches nothing; one that does dispatches CrmEventReceived.
 */
final class CrmEventWebhook
{
    public function __invoke(Request $request): JsonResponse|Response
    {
        $raw = (string) $request->getContent();
        $headers = $request->headers->all();
        $result = CrmEvent::verifyDelivery(
            $raw,
            $headers,
            config('connectors.hubspot.credentials.clientSecret'),
            method: $request->getMethod(),
            url: $request->fullUrl(),
        );
        if (! $result['ok']) {
            return new JsonResponse(['ok' => false, 'reason' => $result['reason']], 401);
        }

        $payload = $raw === '' ? null : json_decode($raw, true, 512, JSON_THROW_ON_ERROR);
        event(new CrmEventReceived($payload, $headers));

        return new JsonResponse(['ok' => true]);
    }
}
